    const { fetch, calls: recordedCalls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/tags')) {
        return jsonResponse({
          tags: [
            { id: 'tag_123', name: 'pro_monthly' },
            { id: 'tag_456', name: 'basic_monthly' },
          ],
        })
      }
      if (req.method === 'POST' && req.url.includes('/tags/tag_123')) {
        return jsonResponse({ added_count: 1, errors: [] }, 200)
      }
      return jsonResponse({ error: 'Not found' }, 404)
    })
    mockFetch = fetch
    calls = recordedCalls
    baseConfig = {
      mailchimpApiKey: 'test-api-key-us1',
      mailchimpDatacenter: 'us1',
      mailchimpListId: 'test-list-id',
      fetch: mockFetch,
    }
  })

  it('successfully adds subscriber to tag on happy path', async () => {
    const payload: StripeWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'customer@example.com',
          metadata: { plan_id: 'pro_monthly' },
          payment_status: 'paid',
          mode: 'subscription',
        },
      },
    }

    const result = await handle(payload, baseConfig)

    expect(result.subscriberEmail).toBe('customer@example.com')
    expect(result.tagId).toBe('tag_123')
    expect(result.addedCount).toBe(1)
    expect(calls).toHaveLength(2)

    expect(calls[0].method).toBe('GET')
    expect(calls[0].url).toBe('https://us1.api.mailchimp.com/3.0/lists/test-list-id/tags')
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-api-key-us1')

    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://us1.api.mailchimp.com/3.0/lists/test-list-id/tags/tag_123')
    expect(calls[1].json).toEqual({
      members: [{ email_address: 'customer@example.com', status: 'subscribed' }],
