        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'customer@example.com',
          metadata: {},
          payment_status: 'paid',
          mode: 'subscription',
        },
      },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing metadata.plan_id')
  })

