    const payload: StripeWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'customer@example.com',
          metadata: { plan_id: 'pro_monthly' },
          payment_status: 'unpaid',
          mode: 'subscription',
        },
      },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Payment status is "unpaid"')
  })

