    const payload: StripeWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'customer@example.com',
          metadata: { plan_id: 'pro_monthly' },
          payment_status: 'paid',
          mode: 'payment',
        },
      },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Checkout mode is "payment"')
  })

  it('throws when tag is not found in Mailchimp', async () => {
    const { fetch, calls: notFoundCalls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/tags')) {
        return jsonResponse({ tags: [{ id: 'tag_456', name: 'basic_monthly' }] })
      }
      return jsonResponse({ error: 'Not found' }, 404)
    })

    const config: ConnectorConfig = {
      ...baseConfig,
      fetch,
    }

    const payload: StripeWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'customer@example.com',
          metadata: { plan_id: 'nonexistent_plan' },
