        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_email: 'customer@example.com',
          metadata: { plan_id: 'pro_monthly' },
          payment_status: 'paid',
          mode: 'subscription',
        },
      },
    }

    await expect(handle(payload, config)).rejects.toThrow('Mailchimp GET tags failed: 401 Unauthorized')
    expect(errorCalls).toHaveLength(1)
  })
})

